          if (game2.global.race["grenadier"]) perSoldier *= 1.75;
          if (game2.global.civic.govern.type === "autocracy") perSoldier *= 1.08;
          else if (game2.global.civic.govern.type === "dictator")
            perSoldier *= 1.12;
