      let storageList = m.priorityList.filter(
        (r) => r.isUnlocked() && r.isManagedStorage()
      );
      if (storageList.length === 0) {
        return;
      }
      let totalCrates = resources2.Crates.currentQuantity;
      let totalContainers = resources2.Containers.currentQuantity;
